// Facility operations persistence: one JSONB row per (tenant, legal entity, agenda) + a files table.
// Owned by ops-scaffold. Agenda lanes do not edit this file; they add commands/state in shared/{commands,domain}.
import { ContextAccess, OperationContextUnavailable } from '@app/core-runtime';
import type { OperationalScope, ScopedTransactionExecutor } from '@app/core-runtime';
import { and, eq, inArray, sql } from 'drizzle-orm';
import { DateTime, Effect, Schema } from 'effect';

import {
  FacilityOperationsPermissionDenied,
  FacilityOperationsPersistenceUnavailable,
  FacilityOperationsReferenceUnavailable,
  FacilityOperationsRevisionConflict,
  FacilityOperationsScopeMismatch,
} from '../../shared/actions/apply-command.ts';
import type { ApplyCommandResult, OpsCommand } from '../../shared/actions/apply-command.ts';
import { MAX_FILE_BYTES, agendaDefinitions, agendaIds, agendaOfCommand } from '../../shared/agendas.ts';
import type { FileUploadCommand } from '../../shared/agendas.ts';
import type { OverviewRequest, OverviewResponse } from '../../shared/apis/overview.ts';
import type { RecordsRequest, RecordsResponse, StoredFile } from '../../shared/apis/records.ts';
import {
  PERSONAL_AGENDA_COMMANDS,
  agendaStateForAssignee,
  agendaStateForPrincipal,
} from '../../shared/domain/agenda.ts';
import type { AgendaState } from '../../shared/domain/agenda.ts';
import { canApplyMeterCommand, meterAccess, operationalMetersState } from '../../shared/domain/meters-access.ts';
import type { MetersState } from '../../shared/domain/meters.ts';
import { FileIdSchema, entityIdOf, mintId, opsConflict } from '../../shared/domain/common.ts';
import {
  CHANGE_LOG_ROW,
  ChangeLogStateSchema,
  MAX_CHANGE_LOG_ENTRIES,
  changeEntries,
  touchedSince,
} from '../../shared/domain/change-log.ts';
import type { ChangeEntry } from '../../shared/domain/change-log.ts';
import type { AgendaId, AgendaSensitivity } from '../../shared/domain/common.ts';
import { opsOverviewOf } from '../../shared/domain/ops-overview.ts';
import { agendaStates, files } from '../database/schema.ts';

export const FACILITY_OPERATIONS_MODULE_ID = 'facility.operations';
/** Context permission keys (permission keys allow only [a-z0-9_] segments). */
export const facilityOperationsPermissions = {
  readAll: 'facility.operations.read_all',
  readOperational: 'facility.operations.read_operational',
  writeAll: 'facility.operations.write_all',
  writeOperational: 'facility.operations.write_operational',
} as const;
type PermissionKey = (typeof facilityOperationsPermissions)[keyof typeof facilityOperationsPermissions];

const unavailable = (cause?: unknown) =>
  Object.defineProperty(
    new FacilityOperationsPersistenceUnavailable({
      code: 'facility_operations_persistence_unavailable',
      reason: 'Facility operations persistence is temporarily unavailable',
    }),
    'cause',
    { enumerable: false, value: cause },
  );

const referenceUnavailable = (cause?: unknown) =>
  Object.defineProperty(
    new FacilityOperationsReferenceUnavailable({
      code: 'facility_operations_reference_unavailable',
      reason: 'Permission evaluation is temporarily unavailable',
    }),
    'cause',
    { enumerable: false, value: cause },
  );

const revisionConflict = () =>
  new FacilityOperationsRevisionConflict({
    code: 'facility_operations_revision_conflict',
    reason: 'The agenda changed; refresh before another operation',
  });

const permissionDenied = (reason: string) =>
  new FacilityOperationsPermissionDenied({ code: 'facility_operations_permission_denied', reason });

export interface Grants {
  readonly readAll: boolean;
  readonly readOperational: boolean;
  readonly writeAll: boolean;
  readonly writeOperational: boolean;
}

/** Access matrix: restricted agendas need *_all; operational agendas accept *_operational too. */
export const canReadAgenda = (grants: Grants, sensitivity: AgendaSensitivity) =>
  grants.readAll ||
  grants.writeAll ||
  (sensitivity === 'operational' && (grants.readOperational || grants.writeOperational));
export const canWriteAgenda = (grants: Grants, sensitivity: AgendaSensitivity) =>
  grants.writeAll || (sensitivity === 'operational' && grants.writeOperational);
/**
 * Operational-only principals (external partners) read just the calendar events assigned to them and never
 * create or change events: the calendar of the company stays with its own staff.
 */
export const isAssignedOnly = (grants: Grants) => !grants.readAll && !grants.writeAll;
const canWriteAgendaEvents = (grants: Grants) =>
  !isAssignedOnly(grants) && canWriteAgenda(grants, agendaDefinitions.agenda.sensitivity);

/** Decoded byte length of a padded base64 string. */
const base64ByteLength = (value: string) => {
  const padding = value.endsWith('==') ? 2 : value.endsWith('=') ? 1 : 0;
  return (value.length / 4) * 3 - padding;
};

/** One bulk SpiceDB check for every Facility Operations context permission of the scope's company. */
export const facilityOperationsGrants = Effect.fn('FacilityOperations.grants')(function* facilityOperationsGrants(
  scope: OperationalScope,
) {
  const access = yield* ContextAccess;
  if (scope.legalEntityId === undefined || access.contextPermissions === undefined) {
    return yield* referenceUnavailable();
  }
  const keys: readonly PermissionKey[] = Object.values(facilityOperationsPermissions);
  const decisions = yield* access.contextPermissions({
    legalEntityId: scope.legalEntityId,
    principalId: scope.principalId,
    targets: keys.map((permission) => ({ moduleId: FACILITY_OPERATIONS_MODULE_ID, permission })),
    tenantId: scope.tenantId,
  });
  const allowed = (permission: PermissionKey) => {
    const decision = decisions.find((entry) => entry.key === `${FACILITY_OPERATIONS_MODULE_ID}:${permission}`);
    return decision?.decision === 'allowed';
  };
  if (decisions.some((entry) => entry.decision === 'unavailable')) {
    return yield* referenceUnavailable();
  }
  return {
    readAll: allowed(facilityOperationsPermissions.readAll),
    readOperational: allowed(facilityOperationsPermissions.readOperational),
    writeAll: allowed(facilityOperationsPermissions.writeAll),
    writeOperational: allowed(facilityOperationsPermissions.writeOperational),
  } satisfies Grants;
});

const recordsAccessList = (granted: Grants) => {
  const meters = meterAccess(granted);
  return agendaIds.map((agenda) => {
    const { sensitivity } = agendaDefinitions[agenda];
    if (agenda === 'meters') {
      return { agenda, canRead: meters.canRead, canWrite: meters.canWrite };
    }
    if (agenda === 'agenda') {
      return { agenda, canRead: canReadAgenda(granted, sensitivity), canWrite: canWriteAgendaEvents(granted) };
    }
    return { agenda, canRead: canReadAgenda(granted, sensitivity), canWrite: canWriteAgenda(granted, sensitivity) };
  });
};

/** The rows a records read needs, exactly as the owner transaction read them (still encoded). */
export interface LoadedFacilityRecords {
  readonly file: StoredFile | undefined;
  readonly rows: ReadonlyMap<string, { readonly revision: number; readonly state: unknown; readonly updatedAt: Date }>;
}

const decodeAgendaRow = Effect.fn('FacilityOperations.decodeAgenda')(function* decodeAgendaRow(
  loaded: LoadedFacilityRecords,
  agenda: AgendaId,
) {
  const definition = agendaDefinitions[agenda];
  const row = loaded.rows.get(agenda);
  const state: unknown = yield* Schema.decodeUnknownEffect(definition.stateSchema)(row?.state ?? definition.empty);
  const updatedAt = row === undefined ? yield* DateTime.now : DateTime.fromDateUnsafe(row.updatedAt);
  return { revision: row?.revision ?? 0, state, updatedAt };
}, Effect.mapError(unavailable));

/**
 * Decodes the loaded rows of the requested agendas the person may read and narrows each to what they may see:
 * own inbox/preferences in the calendar agenda (only assigned events for external partners), meters without
 * financial values without that permission. Records and overview reads both show exactly these states.
 */
const visibleAgendas = Effect.fn('FacilityOperations.visibleAgendas')(function* visibleAgendas(
  requested: readonly AgendaId[],
  loaded: LoadedFacilityRecords,
  granted: Grants,
  scope: OperationalScope,
) {
  const meters = meterAccess(granted);
  const assignedOnly = isAssignedOnly(granted);
  const actorRef = { principalId: scope.principalId, tenantId: scope.tenantId } as RecordsResponse['actorPrincipalRef'];
  let ownEventIds: ReadonlySet<string> | undefined;
  const envelopes = new Map<AgendaId, Readonly<Record<string, unknown>> & { readonly revision: number; readonly state: unknown }>();
  for (const entry of recordsAccessList(granted)) {
    if (!entry.canRead || !requested.includes(entry.agenda)) {
      continue;
    }
    const snapshot = yield* decodeAgendaRow(loaded, entry.agenda);
    envelopes.set(entry.agenda, {
      canWrite: entry.canWrite,
      ...(entry.agenda === 'agenda' && assignedOnly ? { assignedOnly: true as const } : {}),
      ...(entry.agenda === 'meters' ? { canReadFinancial: meters.canReadFinancial, canManage: meters.canManage } : {}),
      revision: snapshot.revision,
      state:
        entry.agenda === 'agenda'
          ? (() => {
              const personal = agendaStateForPrincipal(snapshot.state as AgendaState, actorRef);
              if (!assignedOnly) {
                return personal;
              }
              const own = agendaStateForAssignee(personal, actorRef);
              ownEventIds = new Set(own.events.map((event) => event.id));
              return own;
            })()
          : entry.agenda === 'meters' && !meters.canReadFinancial
            ? operationalMetersState(snapshot.state as MetersState)
            : snapshot.state,
      updatedAt: snapshot.updatedAt,
    });
  }
  return { actorRef, envelopes, ownEventIds };
});

/**
 * After commit: decodes the loaded agenda rows, narrows them to what the person may see, and shapes the
 * records response. No database access.
 */
export const finishFacilityRecords = Effect.fn('FacilityOperations.finishRecords')(function* finishFacilityRecords(
  request: RecordsRequest,
  loaded: LoadedFacilityRecords,
  granted: Grants,
  scope: OperationalScope,
) {
  const assignedOnly = isAssignedOnly(granted);
  const accessList = recordsAccessList(granted);
  const visible = yield* visibleAgendas(request.agendas ?? agendaIds, loaded, granted, scope);
  const { actorRef } = visible;
  let { ownEventIds } = visible;
  const agendas = Object.fromEntries(visible.envelopes);
  const readable = new Set(accessList.filter((entry) => entry.canRead).map((entry) => entry.agenda as string));
  // An operational-only principal sees the history of their own events only, never of other people's.
  if (assignedOnly && request.historyFor !== undefined) {
    if (ownEventIds === undefined) {
      const snapshot = yield* decodeAgendaRow(loaded, 'agenda');
      ownEventIds = new Set(
        agendaStateForAssignee(snapshot.state as AgendaState, actorRef).events.map((event) => event.id),
      );
    }
    if (!ownEventIds.has(request.historyFor)) {
      readable.delete('agenda');
    }
  }
  const historyFor = request.historyFor;
  const changeLog = loaded.rows.get(CHANGE_LOG_ROW)?.state;
  const history =
    historyFor === undefined
      ? undefined
      : changeLog === undefined
        ? ([] as readonly ChangeEntry[])
        : (yield* Schema.decodeUnknownEffect(ChangeLogStateSchema)(changeLog).pipe(
            Effect.mapError(unavailable),
          )).entries
            .filter((entry) => entry.entityId === historyFor && readable.has(entry.agenda))
            .toReversed()
            .slice(0, 200);
  // The read definition validates the result against RecordsResponseSchema (agenda states are typed values).
  const response: RecordsResponse = {
    access: accessList,
    actorPrincipalRef: actorRef,
    agendas: agendas as RecordsResponse['agendas'],
    ...(loaded.file === undefined ? {} : { file: loaded.file }),
    ...(history === undefined ? {} : { history }),
  };
  return response;
});

/**
 * After commit: the overview read. Same visible agenda states as the records read, but only the calendar agenda
 * leaves the server as a document; every other agenda is reduced to its deadlines, open incidents, record count
 * and (on request) search rows. No database access.
 */
export const finishFacilityOverview = Effect.fn('FacilityOperations.finishOverview')(function* finishFacilityOverview(
  request: OverviewRequest,
  loaded: LoadedFacilityRecords,
  granted: Grants,
  scope: OperationalScope,
) {
  const { actorRef, envelopes } = yield* visibleAgendas(agendaIds, loaded, granted, scope);
  const agenda = envelopes.get('agenda');
  // The read definition validates the result against OverviewResponseSchema.
  const response: OverviewResponse = {
    access: recordsAccessList(granted),
    actorPrincipalRef: actorRef,
    ...(agenda === undefined ? {} : { agenda: agenda as NonNullable<OverviewResponse['agenda']> }),
    ...opsOverviewOf(envelopes, request.includeSearch === true),
  };
  return response;
});

export const persistenceService = Effect.fn('FacilityOperations.persistenceService')(
  function* makePersistence(transaction: ScopedTransactionExecutor, scope: OperationalScope) {
    const { legalEntityId } = scope;
    if (
      legalEntityId === undefined ||
      transaction.scope.tenantId !== scope.tenantId ||
      transaction.scope.legalEntityId !== legalEntityId
    ) {
      return yield* new FacilityOperationsScopeMismatch({
        code: 'facility_operations_scope_mismatch',
        reason: 'A scoped company transaction is required',
      });
    }
    const actor = { principalId: scope.principalId, tenantId: scope.tenantId };

    const access = yield* ContextAccess;
    const grants = () => facilityOperationsGrants(scope).pipe(Effect.provideService(ContextAccess, access));

    const whereAgenda = (agenda: AgendaId) =>
      and(
        eq(agendaStates.tenantId, scope.tenantId),
        eq(agendaStates.legalEntityId, legalEntityId),
        eq(agendaStates.agenda, agenda),
      );

    /** Loads one agenda row. A missing row reads as the agenda's empty state at revision 0 (seed may be absent). */
    const load = Effect.fn('FacilityOperations.load')(function* load(agenda: AgendaId) {
      const definition = agendaDefinitions[agenda];
      const rows = yield* transaction
        .select()
        .from(agendaStates)
        .where(whereAgenda(agenda))
        .limit(1)
        .pipe(Effect.mapError(unavailable));
      const [row] = rows;
      const raw: unknown = row === undefined ? definition.empty : row.state;
      const state: unknown = yield* Schema.decodeUnknownEffect(definition.stateSchema)(raw).pipe(
        Effect.mapError(unavailable),
      );
      const updatedAt = row === undefined ? yield* DateTime.now : DateTime.fromDateUnsafe(row.updatedAt);
      return { exists: row !== undefined, raw, revision: row?.revision ?? 0, state, updatedAt };
    });

    const save = Effect.fn('FacilityOperations.save')(function* save(
      agenda: AgendaId,
      snapshot: { readonly exists: boolean; readonly revision: number },
      encoded: unknown,
    ) {
      const now = DateTime.toDateUtc(yield* DateTime.now);
      const next = snapshot.revision + 1;
      if (!snapshot.exists) {
        const inserted = yield* transaction
          .insert(agendaStates)
          .values({
            agenda,
            legalEntityId,
            revision: next,
            state: encoded,
            tenantId: scope.tenantId,
            updatedAt: now,
          })
          .onConflictDoNothing()
          .returning({ revision: agendaStates.revision })
          .pipe(Effect.mapError(unavailable));
        if (inserted.length !== 1) {
          return yield* revisionConflict();
        }
        return next;
      }
      const rows = yield* transaction
        .update(agendaStates)
        .set({ revision: next, state: encoded, updatedAt: now })
        .where(and(whereAgenda(agenda), eq(agendaStates.revision, snapshot.revision)))
        .returning({ revision: agendaStates.revision })
        .pipe(Effect.mapError(unavailable));
      if (rows.length !== 1) {
        return yield* revisionConflict();
      }
      return next;
    });

    const uploadFile = Effect.fn('FacilityOperations.uploadFile')(function* uploadFile(
      command: FileUploadCommand,
      resourceId: string,
    ) {
      const granted = yield* grants();
      if (!canWriteAgenda(granted, agendaDefinitions.documents.sensitivity)) {
        return yield* permissionDenied('File upload requires write access to documents');
      }
      if (command.contentBase64.length % 4 !== 0) {
        return yield* opsConflict('File content is not valid base64');
      }
      const size = base64ByteLength(command.contentBase64);
      if (size > MAX_FILE_BYTES) {
        return yield* opsConflict('File is larger than 5 MB');
      }
      const id = yield* mintId(FileIdSchema, resourceId);
      yield* transaction
        .insert(files)
        .values({
          bytes: sql`decode(${command.contentBase64}, 'base64')`,
          createdBy: scope.principalId,
          id,
          legalEntityId,
          mime: command.mime,
          name: command.name,
          size,
          tenantId: scope.tenantId,
        })
        .pipe(Effect.mapError(unavailable));
      const entity = yield* entityIdOf(id);
      const result: ApplyCommandResult = {
        entityIds: [entity],
        file: { id, mime: command.mime, name: command.name, size },
        revision: 0,
      };
      return result;
    });

    const readFile = Effect.fn('FacilityOperations.readFile')(function* readFile(fileId: string) {
      const rows = yield* transaction
        .select({
          content: sql<string>`encode(${files.bytes}, 'base64')`,
          createdAt: files.createdAt,
          createdBy: files.createdBy,
          id: files.id,
          mime: files.mime,
          name: files.name,
          size: files.size,
        })
        .from(files)
        .where(and(eq(files.tenantId, scope.tenantId), eq(files.legalEntityId, legalEntityId), eq(files.id, fileId)))
        .limit(1)
        .pipe(Effect.mapError(unavailable));
      const [row] = rows;
      if (row === undefined) {
        return undefined;
      }
      const file: StoredFile = {
        // Postgres wraps encode() output every 76 characters.
        contentBase64: row.content.replaceAll('\n', ''),
        createdAt: DateTime.fromDateUnsafe(row.createdAt),
        createdBy: { principalId: row.createdBy, tenantId: scope.tenantId } as StoredFile['createdBy'],
        id: row.id as StoredFile['id'],
        mime: row.mime,
        name: row.name,
        size: row.size,
      };
      return file;
    });

    /** Appends change entries to the company's change-log row in the same transaction (row lock via upsert). */
    const appendHistory = Effect.fn('FacilityOperations.appendHistory')(function* appendHistory(
      entries: readonly unknown[],
    ) {
      if (entries.length === 0) {
        return;
      }
      const now = DateTime.toDateUtc(yield* DateTime.now);
      const fresh = yield* Schema.encodeUnknownEffect(Schema.fromJsonString(Schema.Unknown))(entries).pipe(
        Effect.mapError(unavailable),
      );
      yield* transaction
        .insert(agendaStates)
        .values({
          agenda: CHANGE_LOG_ROW,
          legalEntityId,
          revision: 1,
          state: { entries },
          tenantId: scope.tenantId,
          updatedAt: now,
        })
        .onConflictDoUpdate({
          set: {
            revision: sql`${agendaStates.revision} + 1`,
            state: sql`jsonb_build_object('entries', (
              select coalesce(jsonb_agg(entry order by position), '[]'::jsonb)
              from (
                select entry, position
                from jsonb_array_elements(coalesce(${agendaStates.state}->'entries', '[]'::jsonb) || ${fresh}::jsonb)
                  with ordinality as items(entry, position)
                order by position desc
                limit ${MAX_CHANGE_LOG_ENTRIES}
              ) kept
            ))`,
            updatedAt: now,
          },
          target: [agendaStates.tenantId, agendaStates.legalEntityId, agendaStates.agenda],
        })
        .pipe(Effect.mapError(unavailable));
    });

    /** Personal inbox, preferences and export log are not record history. */
    const loggedCommand = (tag: string) =>
      !tag.startsWith('AgendaNotifications') && tag !== 'AgendaExportRecord' && tag !== 'AgendaPreferencesSet';

    const apply = Effect.fn('FacilityOperations.apply')(function* apply(
      command: OpsCommand,
      expectedRevision: number,
      resourceId: string,
      baseUpdatedAt?: string,
    ) {
      if (command._tag === 'FileUpload') {
        return yield* uploadFile(command, resourceId);
      }
      const definition = agendaOfCommand(command);
      if (definition === undefined) {
        return yield* opsConflict(`No agenda handles command ${command._tag}`);
      }
      const granted = yield* grants();
      const meterCommand =
        command._tag === 'MeterCreate' ||
        command._tag === 'MeterUpdate' ||
        command._tag === 'MeterReadingRecord' ||
        command._tag === 'MeterReadingVoid';
      const agendaCommand = definition.id === 'agenda';
      const mayApply = meterCommand
        ? canApplyMeterCommand(granted, command)
        : agendaCommand && PERSONAL_AGENDA_COMMANDS.has(command._tag)
          ? canReadAgenda(granted, definition.sensitivity)
          : agendaCommand
            ? canWriteAgendaEvents(granted)
            : canWriteAgenda(granted, definition.sensitivity);
      if (!mayApply) {
        return yield* permissionDenied(`Changes in agenda ${definition.id} require write permission`);
      }
      const snapshot = yield* load(definition.id);
      const stale = snapshot.revision !== expectedRevision;
      if (stale && baseUpdatedAt === undefined) {
        return yield* revisionConflict();
      }
      const now = yield* DateTime.now;
      // The reducer always runs against the CURRENT state, so every business rule sees the latest data.
      const change = yield* definition.evolve(snapshot.state, command, { actor, now, resourceId });
      if (stale && baseUpdatedAt !== undefined && touchedSince(snapshot.raw, change.entityIds, baseUpdatedAt)) {
        return yield* revisionConflict();
      }
      const encoded = yield* Schema.encodeUnknownEffect(definition.stateSchema)(change.state).pipe(
        Effect.mapError(unavailable),
      );
      const revision = yield* save(definition.id, snapshot, encoded);
      if (loggedCommand(command._tag)) {
        yield* appendHistory(
          changeEntries({
            after: encoded,
            agenda: definition.id,
            at: DateTime.formatIso(now),
            before: snapshot.raw,
            by: actor,
            command: command._tag,
            entityIds: change.entityIds,
          }),
        );
      }
      const result: ApplyCommandResult = { agenda: definition.id, entityIds: [...change.entityIds], revision };
      return result;
    });

    /**
     * The records read's whole transaction step: one query for every agenda row the request may show (plus the
     * change log for history), and the requested file. Decoding runs after commit in {@link finishFacilityRecords}.
     */
    const loadRecords = Effect.fn('FacilityOperations.loadRecords')(function* loadRecords(
      request: RecordsRequest,
      granted: Grants,
    ) {
      const requested = request.agendas ?? agendaIds;
      const accessList = recordsAccessList(granted);
      const needed = new Set<string>(
        accessList.filter((entry) => entry.canRead && requested.includes(entry.agenda)).map((entry) => entry.agenda),
      );
      if (request.historyFor !== undefined) {
        needed.add(CHANGE_LOG_ROW);
        if (isAssignedOnly(granted)) needed.add('agenda');
      }
      const rows =
        needed.size === 0
          ? []
          : yield* transaction
              .select({
                agenda: agendaStates.agenda,
                revision: agendaStates.revision,
                state: agendaStates.state,
                updatedAt: agendaStates.updatedAt,
              })
              .from(agendaStates)
              .where(
                and(
                  eq(agendaStates.tenantId, scope.tenantId),
                  eq(agendaStates.legalEntityId, legalEntityId),
                  inArray(agendaStates.agenda, [...needed]),
                ),
              )
              .pipe(Effect.mapError(unavailable));
      const documentsReadable = accessList.find((entry) => entry.agenda === 'documents')?.canRead === true;
      const file = request.fileId !== undefined && documentsReadable ? yield* readFile(request.fileId) : undefined;
      return {
        file,
        rows: new Map(rows.map((row) => [row.agenda, row] as const)),
      } satisfies LoadedFacilityRecords;
    });

    return { apply, loadRecords };
  },
  Effect.mapError((cause) =>
    Object.defineProperty(
      new OperationContextUnavailable({
        code: 'operation_context_unavailable',
        reason: 'Owner-scoped services are temporarily unavailable',
      }),
      'cause',
      { enumerable: false, value: cause },
    ),
  ),
);
